// Revenue conversion hook: records paid event on checkout success
// Called by checkout completion endpoint

const fs = require('fs');
const path = require('path');

const REVENUE_LOG = path.join(__dirname, '..', 'data', 'revenue_events.log');

function recordPaidEvent(amount, currency = 'USD') {
  const event = {
    type: 'paid',
    amount,
    currency,
    timestamp: new Date().toISOString(),
    source: 'checkout'
  };
  fs.appendFileSync(REVENUE_LOG, JSON.stringify(event) + '\n');
  // Also increment in-memory counter if available
  if (global.revenueCounters) {
    global.revenueCounters.paidEvents = (global.revenueCounters.paidEvents || 0) + 1;
  }
  return true;
}

module.exports = { recordPaidEvent };
